@use 'abstracts' as *;
@use 'sass:math';

/**
 * GRID SYSTEM
 * 
 * WAÅ»NA INFORMACJA O MEDIA QUERIES I RESPONSYWNOÅšCI:
 * W tym pliku stosujemy specjalny wzorzec "mediaplex" dla media queries.
 * Zamiast zagnieÅ¼dÅ¼aÄ‡ media queries w pÄ™tlach generujÄ…cych klasy,
 * grupujemy wszystkie style dla danego breakpointu razem.
 * 
 * KorzyÅ›ci:
 * 1. Zapewnia to prawidÅ‚owÄ… kolejnoÅ›Ä‡ w wygenerowanym CSS:
 *    - Najpierw podstawowe klasy (bez breakpointÃ³w)
 *    - NastÄ™pnie klasy dla najwiÄ™kszego breakpointu (xl)
 *    - Na koÅ„cu klasy dla najmniejszego breakpointu (xxs)
 * 
 * 2. DziÄ™ki temu style dla mniejszych breakpointÃ³w (np. sm)
 *    sÄ… pÃ³Åºniej w CSS i poprawnie nadpisujÄ… style dla wiÄ™kszych (np. lg)
 * 
 * Kluczowe jest zachowanie porzÄ…dku od najwiÄ™kszego do najmniejszego breakpointu
 * w mapie $breakpoints oraz generowanie oddzielnych blokÃ³w @media dla kaÅ¼dego breakpointu.
 */


%grid {
    display: grid;
    grid-template-columns: minmax(1rem, 1fr) repeat(12, minmax(0, calc((#{$page-width} - 11 * #{$page-gap}) / 12))) minmax(1rem, 1fr);
    gap: $page-gap;
    row-gap: 0;
    @include media($breakpoint-sm) {
        gap: 0;
        row-gap: 16px;
    }
}

.flex {
    display: flex;
}

.grid-l-50 {
    grid-column: 1/8;
    grid-row: 1/2;
}

.grid-p-50 {
    grid-column: 8/15;
    grid-column: 1/2;
}

.grid {
    @extend %grid;
}

.align-center {
    align-items: center;
}
.justify-center {
    justify-content: center;
}
.align-start {
    align-items: start;
}
.justify-start {
    justify-content: start;
}
.align-end {
    align-items: end;
}
.justify-end {
    justify-content: end;
}
.justify-between {
    justify-content: space-between;
}
.justify-around {
    justify-content: space-around;
}
.justify-evenly {
    justify-content: space-evenly;
}

// DomyÅ›lna liczba wierszy rÃ³wna liczbie kolumn
$grid-rows: $grid-columns !default;

// DefiniujÄ™ mapÄ™ z breakpointami (od najwiÄ™kszego do najmniejszego)
// Ta kolejnoÅ›Ä‡ jest kluczowa dla prawidÅ‚owego nadpisywania styli w media queries
$breakpoints: (
  "xl": $breakpoint-xl,
  "lg": $breakpoint-lg,
  "md": $breakpoint-md,
  "sm": $breakpoint-sm,
  "xs": $breakpoint-xs,
  "xxs": $breakpoint-xxs
);

// Mixin do ustawiania grid-column
@mixin grid-column-pos($start, $end) {
  grid-column: #{$start}/#{$end};
}

// Mixin do ustawiania grid-row
@mixin grid-row-pos($start, $end) {
  grid-row: #{$start}/#{$end};
}

// Generowanie klas utility dla kolumn
// Najpierw generujemy podstawowe klasy bez media queries
@for $i from 1 through ($grid-columns + 2) {
  @for $j from ($i + 1) through ($grid-columns + 3) {
    .gc-#{$i}\/#{$j} {
      @include grid-column-pos($i, $j);
    }
  }
}

// Potem generujemy media queries osobno, wyraÅºnie oddzielone dla kaÅ¼dego breakpointu
// DziÄ™ki temu wszystkie media queries dla danego breakpointu bÄ™dÄ… zgrupowane razem
// Zaczynamy od najwiÄ™kszego breakpointu (xl) i idziemy do najmniejszego (xxs)
// KolejnoÅ›Ä‡ ma znaczenie! Najmniejsze breakpointy bÄ™dÄ… na koÅ„cu pliku i nadpiszÄ… wiÄ™ksze
@each $breakpoint-name, $breakpoint-value in $breakpoints {
  @media screen and (max-width: #{$breakpoint-value}) {
    @for $i from 1 through ($grid-columns + 2) {
      @for $j from ($i + 1) through ($grid-columns + 3) {
        .gc-#{$breakpoint-name}-#{$i}\/#{$j} {
          grid-column: #{$i}/#{$j} !important;
        }
      }
    }
  }
}

// Generowanie klas utility dla wierszy
// Najpierw generujemy podstawowe klasy bez media queries
@for $i from 1 through $grid-rows {
  @for $j from ($i + 1) through ($grid-rows + 2) {
    .gr-#{$i}\/#{$j} {
      @include grid-row-pos($i, $j);
    }
  }
}

// Potem generujemy media queries osobno dla kaÅ¼dego breakpointu
// PorzÄ…dek od najwiÄ™kszego do najmniejszego breakpointu
@each $breakpoint-name, $breakpoint-value in $breakpoints {
  @media screen and (max-width: #{$breakpoint-value}) {
    @for $i from 1 through $grid-rows {
      @for $j from ($i + 1) through ($grid-rows + 2) {
        .gr-#{$breakpoint-name}-#{$i}\/#{$j} {
          grid-row: #{$i}/#{$j} !important;
        }
      }
    }
  }
}


// Generowanie klas dla gaps
@function get-gap-class-name($value) {
  // Konwersja 0.25 -> 25, 0.5 -> 50, 1 -> 100, 1.25 -> 125 itd.
  $class-value: $value * 100;
  // Zamiana na string bez kropki dziesiÄ™tnej
  @return $class-value;
}

// Generowanie klas utility dla gap i row-gap
$gap-min: 0;
$gap-max: 5;
$gap-step: 0.25;

// Najpierw generujemy podstawowe klasy gap bez media queries
@for $i from 0 through math.div($gap-max - $gap-min, $gap-step) {
  $current-value: $gap-min + $i * $gap-step;
  $class-suffix: get-gap-class-name($current-value);
  
  .gap-#{$class-suffix} {
    gap: #{$current-value}rem;
  }
  
  .row-gap-#{$class-suffix} {
    row-gap: #{$current-value}rem;
  }
  
  .column-gap-#{$class-suffix} {
    column-gap: #{$current-value}rem;
  }
}

// NastÄ™pnie generujemy responsywne klasy gap dla kaÅ¼dego breakpointu osobno
// PorzÄ…dek od najwiÄ™kszego do najmniejszego breakpointu
@each $breakpoint-name, $breakpoint-value in $breakpoints {
  @media screen and (max-width: #{$breakpoint-value}) {
    @for $i from 0 through math.div($gap-max - $gap-min, $gap-step) {
      $current-value: $gap-min + $i * $gap-step;
      $class-suffix: get-gap-class-name($current-value);
      
      .gap-#{$breakpoint-name}-#{$class-suffix} {
        gap: #{$current-value}rem !important;
      }
      
      .row-gap-#{$breakpoint-name}-#{$class-suffix} {
        row-gap: #{$current-value}rem !important;
      }
      
      .column-gap-#{$breakpoint-name}-#{$class-suffix} {
        column-gap: #{$current-value}rem !important;
      }
    }
  }
}

